const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = light_page_header

async function light_page_header(opts = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    data: ondata,
    icons: iconject,
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  let dricons = []

  shadow.innerHTML = `
        <div class="header-container">
   
        </div>
        <style></style>
    `

  const style = shadow.querySelector('style')
  const container = shadow.querySelector('.header-container')

  await sdb.watch(onbatch)

  const { io } = net(id)
  io.on.home_contents = function (m) {
    if (m.type === 'update') ondata([m.data])
  }
  el.invite = io.invite('home_contents', { light_page_header: id })

  return el

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  async function ondata(data) {
    const { wallet, amount } = data[0]

    let heading = ""
    let icon = ""
    let display_amount = amount > 0 ? amount : "0.00"

    if (wallet == "btc") {
      heading = "Bitcoin Wallet"
      icon = dricons[0]
    } else if (wallet == "lightning") {
      heading = "Lightning Wallet"
      icon = dricons[1]
      display_amount = Number.isFinite(Number(amount))
        ? Number(amount).toFixed(7)
        : "0.0000000"
    } else {
      console.log("Wrong wallet")
    }

    container.innerHTML = `
          <div class="heading">${heading}</div>
          <div class="wallet-row">
            <div class="icon-slot">${icon}</div>
            <div class="wallet-amount">${display_amount}</div>
          </div>
      `
  }


  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  function iconject(data) {
    dricons = data
  }
}

function fallback_module() {
  return {
    api: fallback_instance,
    _: { 'net_helper': { $: '' } }
  }

  function fallback_instance(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    return {
      drive: {
        'icons/': {
          'btc.svg': {
            '$ref': 'btc.svg'
          },
          'lightning.svg': {
            '$ref': 'lightning.svg'
          },
        },
        'style/': {
          'style.css': {
            '$ref': 'light_page_header.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      }
    }
  }
}
